from pysat.solvers import Glucose3

def solve_with_pysat():
    num_cliques = 9
    vertices_per_clique = 3
    num_vertices = num_cliques * vertices_per_clique
    num_edges = 51

    # Variables: x[j][i] is the label of vertex i in clique j.
    # Labels are 0..51.
    # We need to map these to boolean variables.
    # Let v_{j,i,l} be true if vertex i in clique j has label l.

    solver = Glucose3()

    # v_{j,i,l} for j in 0..8, i in 0..2, l in 0..51
    def get_var(j, i, l):
        return j * (vertices_per_clique * 52) + i * 52 + l + 1

    # Each vertex has exactly one label
    for j in range(num_cliques):
        for i in range(vertices_per_clique):
            solver.add_clause([get_var(j, i, l) for l in range(52)])
            for l1 in range(52):
                for l2 in range(l1 + 1, 52):
                    solver.add_clause([-get_var(j, i, l1), -get_var(j, i, l2)])

    # Each label is used at most once
    for l in range(52):
        vars_with_label_l = [get_var(j, i, l) for j in range(num_cliques) for i in range(vertices_per_clique)]
        for i1 in range(len(vars_with_label_l)):
            for i2 in range(i1 + 1, len(vars_with_label_l)):
                solver.add_clause([-vars_with_label_l[i1], -vars_with_label_l[i2]])

    # Edge labels: e_{k, d} is true if edge k has label d (d in 1..51)
    # There are 51 edges.
    def get_edge_var(k, d):
        return 27 * 52 + k * 52 + d

    # Each edge has exactly one label
    edges = []
    for j in range(num_cliques):
        edges.append((j, 0, j, 1))
        edges.append((j, 1, j, 2))
        edges.append((j, 2, j, 0))
    for j in range(num_cliques - 1):
        for i in range(vertices_per_clique):
            edges.append((j, i, j+1, i))

    for k in range(num_edges):
        solver.add_clause([get_edge_var(k, d) for d in range(1, 52)])
        for d1 in range(1, 52):
            for d2 in range(d1 + 1, 52):
                solver.add_clause([-get_edge_var(k, d1), -get_edge_var(k, d2)])

    # Each edge label is used at most once
    for d in range(1, 52):
        vars_with_edge_label_d = [get_edge_var(k, d) for k in range(num_edges)]
        for k1 in range(len(vars_with_edge_label_d)):
            for k2 in range(k1 + 1, len(vars_with_edge_label_d)):
                solver.add_clause([-vars_with_edge_label_d[k1], -vars_with_edge_label_d[k2]])

    # Edge label constraint: |label(u) - label(v)| = d
    # For each edge k=(j1, i1, j2, i2) and label d:
    # If vertex (j1, i1) has label l1 and vertex (j2, i2) has label l2, then |l1 - l2| = d
    for k in range(num_edges):
        j1, i1, j2, i2 = edges[k]
        for l1 in range(52):
            for l2 in range(52):
                d = abs(l1 - l2)
                if d >= 1:
                    # If vertex (j1, i1) has l1 AND vertex (j2, i2) has l2, then edge k has label d
                    # - (v_{j1,i1,l1} AND v_{j2,i2,l2}) OR e_{k,d}
                    solver.add_clause([-get_var(j1, i1, l1), -get_var(j2, i2, l2), get_edge_var(k, d)])

    if solver.solve():
        model = solver.get_model()
        result = []
        for j in range(num_cliques):
            for i in range(vertices_per_clique):
                for l in range(52):
                    if model[get_var(j, i, l) - 1] > 0:
                        result.append(l)
                        break
        return result
    else:
        return None

